/* One scale and anchor for every object-effect renderer. */
(function(){'use strict';const M=Motion,F=M.sceneFX,old=F.object;const headEffects=new Set(['discovery','snore','bad-smell','sparkles','hearts','sweat','tears','anger','question','idea-bulb','dizzy-stars','steam','warning','thought-cloud','overwhelm-scribble','time-pressure','task-complete','energy-charge','energy-drain','progress-rise','distraction-pings']);
F.object=function(c,o,t,phase){if(!o.effects?.length)return;for(const effect of o.effects){const mode=o.effectAnchor||'auto',head=o.type==='character'&&(mode==='head'||mode==='auto'&&headEffects.has(effect));let x=0,y=0,w=o.w,h=o.h;if(head){const j=o.characterDef&&M.customJoints?M.customJoints(o,t):M.joints(o,t);const p=j?.head||[80,68];x=(p[0]/160-.5)*o.w;y=(p[1]/350-.5)*o.h;w=Math.max(o.w*.65,o.h*.22);h=o.h*.25;}const size=Number.isFinite(o.effectSize)?Math.max(.3,Math.min(4,o.effectSize)):1;c.save();c.translate(x+(o.effectOffsetX||0),y+(o.effectOffsetY||0));c.scale(size,size);old(c,{...o,w,h,effects:[effect],effectSize:1},t,phase);c.restore()}};
M.gazeDirections={direct:[0,0],left:[-1,0],right:[1,0],up:[0,-1],down:[0,1],'up-left':[-1,-1],'up-right':[1,-1],'down-left':[-1,1],'down-right':[1,1]};M.gazeOffset=o=>{const a=M.gazeDirections[o.gaze]||[0,0];return [a[0]*(o.flip?-1:1)*(o.gazeMirror?-1:1)*3,a[1]*3]};})();
